window.marchStdlib = window.marchStdlib || {};
window.marchStdlib["control.march"] = "-- Control: the pure core of the in-cluster control plane (distributed-deploys\n-- build step 12a). Design: specs/plans/2026-09-28-dd-step12-control-plane-design.md,\n-- sections 3, 4, 7 and 8, decisions D37-D41.\n--\n-- The control plane holds no root keys (D37). forge writes and signs a\n-- RELEASE: a sequence number, the digest of its parent, the environment, the\n-- topology digest, the builds it ships, and an ordered list of steps with host\n-- selectors and gates. The leader only executes it:\n--\n--   * `parse` / `serialize` read and write the release's text form (section 4);\n--     `check` validates it, `digest` / `verify` / `sign` cover its identity and\n--     its operator signature, and `accept` is the leader's compare-and-set on\n--     `parent`.\n--   * `pass` is the executor, level-triggered and pure: its inputs are the\n--     newest release held, the membership (which node is in which pool), what\n--     each Agent last reported, the nodes with an order outstanding, and the\n--     time. It finds the first step whose selected nodes do not yet report the\n--     step's end state and orders the next nodes the step allows. Nothing else\n--     is carried between passes, so a new leader resumes a half-finished\n--     rollout from observation alone. A failed step or gate HALTS the release;\n--     the executor never rolls back (a rollback is a new release).\n--   * `Leader` wraps `pass` in the few facts a leader keeps in memory: the\n--     reports (`Obs`, with the leader-clock time each node became healthy, so a\n--     gate window restarts on a new leader, section 4), orders in flight, and a\n--     sticky halt.\n--   * `agent_apply` is the Agent's side of one `StepOrder`, over an `AgentOps`\n--     dictionary: the node's reload server and CAS are reached through it. Until\n--     the `reload_request` builtin exists (design section 6) the dictionary is\n--     the seam tests and the real Agent plug into.\n--   * The payloads of the control protocols (section 7): `AgentReport`,\n--     `StepOrder`, `StepResult`, `CtlChunk`, and the `ControlOps` dictionary a\n--     leader's `Ctl` session is driven by. The `Ctl` and `CtlFetch`\n--     declarations themselves live in test/session/control_peers.march for\n--     now. A protocol may live in a stdlib module since 2026-10-03\n--     (specs/progress/2026-10-03-endpoints-protocol-in-nested-module.md); the\n--     move is specs/todos/2026-09-28-dd-step12a-control-wiring.md.\n--\n-- The leader itself is `count = 1` placement over SWIM with no strict lease\n-- (D40): two leaders during a partition each drive their side toward the\n-- newest release they hold, and nodes refuse anything older (12-pre).\n--\n-- Everything but the Agent's real ops, signing and verifying is pure, so the\n-- examples build one small release (`rel`, in `parse`) and a simulated node and\n-- follow it through the executor; later examples reuse earlier bindings.\n--\n-- doc: try\nmod Control do\n  -- \u2500\u2500 the release document \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- Which of a step's target nodes the step applies to.\n  type CtlHosts = HostsCanary(Int) | HostsRest | HostsAll\n  derive Eq for CtlHosts\n\n  -- What a step does to a node: activate a build's patch, apply the\n  -- release's topology, drain, or take the release's certificate and\n  -- revocation items (step 12b).\n  type CtlAction = DoActivate(String) | DoTopology | DoDrain | DoCerts\n  derive Eq for CtlAction\n\n  -- What must hold after a step before the next one starts. `Healthy(ms)`:\n  -- every node the step selected reports healthy for `ms`.\n  type CtlGate = GateNone | GateHealthy(Int)\n  derive Eq for CtlGate\n\n  -- One rollout step. `pools` is the pools it targets (`[\"*\"]` for every\n  -- pool), `batch` how many of its nodes may have an order outstanding at\n  -- once (0: no limit).\n  type CtlStep = { id : Int, pools : List(String), hosts : CtlHosts, action : CtlAction, gate : CtlGate, batch : Int }\n\n  -- A build the release ships: the base binary's hash and the patch\n  -- manifest's hash.\n  type CtlBuild = { name : String, base : String, manifest : String }\n\n  -- The release's drain: sessions on epochs up to `epoch` drain, with a soft\n  -- then a hard deadline in ms.\n  type CtlDrain = { epoch : Int, soft_ms : Int, hard_ms : Int }\n\n  -- An operator-signed request line the Agent relays to its node's reload\n  -- server for a step (the `SEQ ...` wrapper of 12-pre). The node verifies\n  -- it; the control plane only carries it.\n  type CtlLine = { step : Int, text : String }\n\n  -- A certificate item (step 12b): an operator-signed node certificate, in\n  -- `NodeCert`'s text form, for the node named [node]. The release is signed\n  -- by the deploy key and the certificate by the operator key, and the node\n  -- checks both (D37: a compromised leader can forge neither). The control\n  -- plane issues nothing (D39): `forge cluster cert --deliver` writes these.\n  type CtlCert = { node : String, cert : String }\n\n  -- A release (design section 4). `signature` is the operator's ed25519\n  -- signature, hex, over `signed_text`; the document writes it as `sig`.\n  type CtlRelease = {\n    seq : Int, parent : String, env : String, topology : String,\n    builds : List(CtlBuild), steps : List(CtlStep), lines : List(CtlLine),\n    certs : List(CtlCert), revokes : List(String),\n    drain : Option(CtlDrain), signature : String\n  }\n\n  doc \"\"\"\n  The `parent` of the first release of an environment.\n\n  ## Examples\n\n      march> Control.no_parent()\n      \"none\"\n  \"\"\"\n  fn no_parent() : String do \"none\" end\n\n  -- \u2500\u2500 parsing \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn words(line : String) : List(String) do\n    List.filter(String.split(String.replace_all(line, \"\\t\", \" \"), \" \"), fn w -> w != \"\")\n  end\n\n  pfn int_of(s : String, what : String) : Result(Int, String) do\n    match string_to_int(s) do\n      Some(n) -> Ok(n)\n      None -> Err(what ++ \": not a number: \" ++ s)\n    end\n  end\n\n  doc \"\"\"\n  A duration: `250ms`, `60s`, `2m`, or a bare number of milliseconds.\n  `Err` when the number part is not an integer.\n\n  ## Examples\n\n      march> Control.parse_duration(\"250ms\")\n      Ok(250)\n      march> Control.parse_duration(\"2m\")\n      Ok(120000)\n      march> Control.parse_duration(\"1500\")\n      Ok(1500)\n      march> Control.parse_duration(\"soon\")\n      Err(\"duration: not a number: soon\")\n  \"\"\"\n  fn parse_duration(s : String) : Result(Int, String) do\n    if String.ends_with(s, \"ms\") do int_of(String.slice(s, 0, String.byte_size(s) - 2), \"duration\")\n    else if String.ends_with(s, \"s\") do Result.map(int_of(String.slice(s, 0, String.byte_size(s) - 1), \"duration\"), fn n -> n * 1000)\n    else if String.ends_with(s, \"m\") do Result.map(int_of(String.slice(s, 0, String.byte_size(s) - 1), \"duration\"), fn n -> n * 60000)\n    else int_of(s, \"duration\") end end end\n  end\n\n  doc \"\"\"\n  A duration written the way `parse_duration` reads it back: whole seconds as `Ns`, else `Nms`\n  (so 0 and negative durations are written in ms).\n\n  ## Examples\n\n      march> Control.show_duration(60000)\n      \"60s\"\n      march> Control.show_duration(1500)\n      \"1500ms\"\n      march> Control.show_duration(0)\n      \"0ms\"\n  \"\"\"\n  fn show_duration(ms : Int) : String do\n    if ms > 0 && ms % 1000 == 0 do int_to_string(ms / 1000) ++ \"s\" else int_to_string(ms) ++ \"ms\" end\n  end\n\n  -- `key:value`, the value after the first `:`.\n  pfn field(w : String, key : String) : Option(String) do\n    let p = key ++ \":\"\n    if String.starts_with(w, p) do Some(String.slice(w, String.byte_size(p), String.byte_size(w) - String.byte_size(p)))\n    else None end\n  end\n\n  -- `name(arg)` -> arg\n  pfn call_arg(w : String, name : String) : Option(String) do\n    let p = name ++ \"(\"\n    if String.starts_with(w, p) && String.ends_with(w, \")\") do\n      Some(String.slice(w, String.byte_size(p), String.byte_size(w) - String.byte_size(p) - 1))\n    else None end\n  end\n\n  pfn parse_hosts(v : String) : Result(CtlHosts, String) do\n    if v == \"rest\" do Ok(HostsRest)\n    else if v == \"all\" do Ok(HostsAll)\n    else match call_arg(v, \"canary\") do\n      Some(n) -> Result.map(int_of(n, \"canary\"), fn k -> HostsCanary(k))\n      None -> Err(\"hosts: expected canary(n), rest or all, got \" ++ v)\n    end end end\n  end\n\n  pfn parse_action(v : String) : Result(CtlAction, String) do\n    if v == \"topology\" do Ok(DoTopology)\n    else if v == \"drain\" do Ok(DoDrain)\n    else if v == \"certs\" do Ok(DoCerts)\n    else match call_arg(v, \"activate\") do\n      Some(b) -> if b == \"\" do Err(\"do: activate() names no build\") else Ok(DoActivate(b)) end\n      None -> Err(\"do: expected activate(build), topology, drain or certs, got \" ++ v)\n    end end end end\n  end\n\n  pfn parse_gate(v : String) : Result(CtlGate, String) do\n    if v == \"none\" do Ok(GateNone)\n    else match call_arg(v, \"healthy\") do\n      Some(d) -> Result.map(parse_duration(d), fn ms -> GateHealthy(ms))\n      None -> Err(\"gate: expected healthy(duration) or none, got \" ++ v)\n    end end\n  end\n\n  -- One `key:value` word of a step line into [st]; the three required keys\n  -- are counted in [seen] as a bit set (pools 1, hosts 2, do 4).\n  pfn step_word(st : CtlStep, seen : Int, w : String, id_w : String) : Result((CtlStep, Int), String) do\n    match field(w, \"pools\") do\n      Some(v) -> Ok(({ st with pools: List.filter(String.split(v, \",\"), fn p -> p != \"\") }, int_or(seen, 1)))\n      None -> match field(w, \"hosts\") do\n        Some(v) -> Result.map(parse_hosts(v), fn h -> ({ st with hosts: h }, int_or(seen, 2)))\n        None -> match field(w, \"do\") do\n          Some(v) -> Result.map(parse_action(v), fn a -> ({ st with action: a }, int_or(seen, 4)))\n          None -> match field(w, \"gate\") do\n            Some(v) -> Result.map(parse_gate(v), fn g -> ({ st with gate: g }, seen))\n            None -> match field(w, \"batch\") do\n              Some(v) -> Result.map(int_of(v, \"batch\"), fn b -> ({ st with batch: b }, seen))\n              None -> Err(\"step \" ++ id_w ++ \": unknown field \" ++ w)\n            end\n          end\n        end\n      end\n    end\n  end\n\n  pfn step_words(st : CtlStep, seen : Int, ws : List(String), id_w : String) : Result((CtlStep, Int), String) do\n    match ws do\n      Nil -> Ok((st, seen))\n      Cons(w, rest) ->\n        match step_word(st, seen, w, id_w) do\n          Ok((st2, seen2)) -> step_words(st2, seen2, rest, id_w)\n          Err(e) -> Err(e)\n        end\n    end\n  end\n\n  pfn parse_step(id_w : String, rest : List(String)) : Result(CtlStep, String) do\n    let? id = int_of(id_w, \"step\")\n    let blank = { id: id, pools: Nil, hosts: HostsAll, action: DoTopology, gate: GateNone, batch: 0 }\n    let? (st, seen) = step_words(blank, 0, rest, id_w)\n    if int_and(seen, 1) == 0 do Err(\"step \" ++ id_w ++ \": missing pools:\")\n    else if int_and(seen, 2) == 0 do Err(\"step \" ++ id_w ++ \": missing hosts:\")\n    else if int_and(seen, 4) == 0 do Err(\"step \" ++ id_w ++ \": missing do:\")\n    else Ok(st) end end end\n  end\n\n  pfn parse_build(ws : List(String)) : Result(CtlBuild, String) do\n    match ws do\n      Cons(name, Cons(b, Cons(m, Nil))) ->\n        match (field(b, \"base\"), field(m, \"manifest\")) do\n          (Some(base), Some(man)) -> Ok({ name: name, base: base, manifest: man })\n          _ -> Err(\"build \" ++ name ++ \": expected base:<hash> manifest:<hash>\")\n        end\n      _ -> Err(\"build: expected <name> base:<hash> manifest:<hash>\")\n    end\n  end\n\n  pfn parse_drain(ws : List(String)) : Result(CtlDrain, String) do\n    match ws do\n      Cons(e, Cons(s, Cons(h, Nil))) ->\n        if String.starts_with(e, \"epoch<=\") do\n          match (int_of(String.slice(e, 7, String.byte_size(e) - 7), \"drain epoch\"), field(s, \"soft\"), field(h, \"hard\")) do\n            (Ok(epoch), Some(sv), Some(hv)) ->\n              match (int_of(sv, \"drain soft\"), int_of(hv, \"drain hard\")) do\n                (Ok(soft), Ok(hard)) -> Ok({ epoch: epoch, soft_ms: soft, hard_ms: hard })\n                (Err(x), _) -> Err(x)\n                (_, Err(x)) -> Err(x)\n              end\n            (Err(x), _, _) -> Err(x)\n            _ -> Err(\"drain: expected soft:<ms> hard:<ms>\")\n          end\n        else Err(\"drain: expected epoch<=<n>\") end\n      _ -> Err(\"drain: expected epoch<=<n> soft:<ms> hard:<ms>\")\n    end\n  end\n\n  -- The text of a `line` entry: everything after `line <step> `, single-spaced.\n  pfn parse_signed_line(ws : List(String)) : Result(CtlLine, String) do\n    match ws do\n      Cons(n, Cons(w, rest)) ->\n        let? step = int_of(n, \"line\")\n        Ok({ step: step, text: String.join(Cons(w, rest), \" \") })\n      _ -> Err(\"line: expected <step> <signed request line>\")\n    end\n  end\n\n  pfn empty_release() : CtlRelease do\n    { seq: 0, parent: \"\", env: \"\", topology: \"\", builds: Nil, steps: Nil, lines: Nil, certs: Nil, revokes: Nil,\n      drain: None, signature: \"\" }\n  end\n\n  pfn parse_entry(r : CtlRelease, ws : List(String)) : Result(CtlRelease, String) do\n    match ws do\n      Cons(\"seq\", Cons(v, Nil)) -> Result.map(int_of(v, \"seq\"), fn n -> { r with seq: n })\n      Cons(\"parent\", Cons(v, Nil)) -> Ok({ r with parent: v })\n      Cons(\"env\", Cons(v, Nil)) -> Ok({ r with env: v })\n      Cons(\"topology\", Cons(v, Nil)) -> Ok({ r with topology: v })\n      Cons(\"sig\", Cons(v, Nil)) -> Ok({ r with signature: if v == \"-\" do \"\" else v end })\n      Cons(\"build\", rest) -> Result.map(parse_build(rest), fn b -> { r with builds: List.append(r.builds, [b]) })\n      Cons(\"step\", Cons(n, rest)) -> Result.map(parse_step(n, rest), fn s -> { r with steps: List.append(r.steps, [s]) })\n      Cons(\"line\", rest) -> Result.map(parse_signed_line(rest), fn l -> { r with lines: List.append(r.lines, [l]) })\n      Cons(\"cert\", Cons(n, Cons(text, Nil))) -> Ok({ r with certs: List.append(r.certs, [{ node: n, cert: text }]) })\n      Cons(\"cert\", _) -> Err(\"cert: expected <node> <certificate text>\")\n      Cons(\"revoke\", Cons(text, Nil)) -> Ok({ r with revokes: List.append(r.revokes, [text]) })\n      Cons(\"revoke\", _) -> Err(\"revoke: expected <revocation token>\")\n      Cons(\"drain\", rest) ->\n        match r.drain do\n          Some(_) -> Err(\"drain: given twice\")\n          None -> Result.map(parse_drain(rest), fn d -> { r with drain: Some(d) })\n        end\n      Cons(k, _) -> Err(\"unknown entry `\" ++ k ++ \"`\")\n      Nil -> Ok(r)\n    end\n  end\n\n  pfn parse_lines(r : CtlRelease, lines : List(String), n : Int, after_sig : Bool) : Result(CtlRelease, String) do\n    match lines do\n      Nil -> Ok(r)\n      Cons(l, rest) ->\n        let ws = words(l)\n        match ws do\n          Nil -> parse_lines(r, rest, n + 1, after_sig)\n          Cons(k, _) ->\n            if after_sig do Err(\"line \" ++ int_to_string(n) ++ \": nothing may follow `sig`\")\n            else match parse_entry(r, ws) do\n              Err(e) -> Err(\"line \" ++ int_to_string(n) ++ \": \" ++ e)\n              Ok(r2) -> parse_lines(r2, rest, n + 1, k == \"sig\")\n            end end\n        end\n    end\n  end\n\n  doc \"\"\"\n  Parse a release document (design section 4). The first non-blank line must\n  be `release v1`; words may be separated by any run of spaces, and `sig -`\n  stands for an unsigned release. The result is `check`ed, so an `Ok` release\n  is well formed (not yet verified: see `verify`).\n\n  `Err` names the line: an unknown entry, a malformed step, anything after `sig`, or a\n  failed `check`.\n\n  ## Examples\n\n  `rel` is a two-step release (a canary, then the rest) used by the examples further\n  down; it round-trips through its text form:\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Result.map(Control.parse(Control.serialize(rel)), fn r -> List.length(r.steps))\n      Ok(2)\n      march> Control.parse(\"release v1\\nseq x\")\n      Err(\"line 2: seq: not a number: x\")\n      march> Control.parse(\"release v2\")\n      Err(\"expected `release v1` first, got `release v2`\")\n      march> Control.parse(\"\")\n      Err(\"empty release\")\n  \"\"\"\n  fn parse(text : String) : Result(CtlRelease, String) do\n    let lines = String.split(String.replace_all(text, \"\\r\", \"\"), \"\\n\")\n    let body = List.drop_while(lines, fn l -> words(l) == Nil)\n    match body do\n      Cons(first, rest) ->\n        if words(first) != [\"release\", \"v1\"] do Err(\"expected `release v1` first, got `\" ++ String.trim(first) ++ \"`\")\n        else\n          let? r = parse_lines(empty_release(), rest, 2 + List.length(lines) - List.length(body), false)\n          let? _ = check(r)\n          Ok(r)\n        end\n      Nil -> Err(\"empty release\")\n    end\n  end\n\n  -- \u2500\u2500 checks \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn find_build(r : CtlRelease, name : String) : Option(CtlBuild) do\n    List.find(r.builds, fn b -> b.name == name)\n  end\n\n  pfn check_hosts(where : String, h : CtlHosts) : Result((), String) do\n    match h do\n      HostsCanary(n) -> if n < 1 do Err(where ++ \"canary(n) needs n >= 1\") else Ok(()) end\n      _ -> Ok(())\n    end\n  end\n\n  pfn check_gate(where : String, g : CtlGate) : Result((), String) do\n    match g do\n      GateHealthy(ms) -> if ms <= 0 do Err(where ++ \"healthy(window) needs a positive window\") else Ok(()) end\n      GateNone -> Ok(())\n    end\n  end\n\n  pfn check_action(where : String, r : CtlRelease, a : CtlAction) : Result((), String) do\n    match a do\n      DoActivate(b) -> match find_build(r, b) do\n        Some(_) -> Ok(())\n        None -> Err(where ++ \"activates build `\" ++ b ++ \"`, which the release does not ship\")\n      end\n      DoDrain -> match r.drain do\n        Some(_) -> Ok(())\n        None -> Err(where ++ \"drains, but the release has no `drain` line\")\n      end\n      DoTopology -> Ok(())\n      DoCerts ->\n        if List.is_empty(r.certs) && List.is_empty(r.revokes) do Err(where ++ \"delivers certificates, but the release carries no `cert` or `revoke` item\")\n        else Ok(()) end\n    end\n  end\n\n  pfn check_steps(r : CtlRelease, steps : List(CtlStep), expect : Int) : Result((), String) do\n    match steps do\n      Nil -> Ok(())\n      Cons(s, rest) ->\n        let where = \"step \" ++ int_to_string(s.id) ++ \": \"\n        if s.id != expect do Err(where ++ \"steps must be numbered 1, 2, ... in order (expected \" ++ int_to_string(expect) ++ \")\")\n        else if s.pools == Nil do Err(where ++ \"names no pool\")\n        else if s.batch < 0 do Err(where ++ \"batch must not be negative\")\n        else\n          let? _ = check_hosts(where, s.hosts)\n          let? _ = check_gate(where, s.gate)\n          let? _ = check_action(where, r, s.action)\n          check_steps(r, rest, expect + 1)\n        end end end\n    end\n  end\n\n  pfn dup_build(bs : List(CtlBuild)) : Option(String) do\n    match bs do\n      Nil -> None\n      Cons(b, rest) -> if List.any(rest, fn o -> o.name == b.name) do Some(b.name) else dup_build(rest) end\n    end\n  end\n\n  pfn dup_cert(cs : List(CtlCert)) : Option(String) do\n    match cs do\n      Nil -> None\n      Cons(c, rest) -> if List.any(rest, fn o -> o.node == c.node) do Some(c.node) else dup_cert(rest) end\n    end\n  end\n\n  -- The release's certificate and revocation items, structurally: each\n  -- decodes, one certificate per node, and a `do:certs` step to deliver them.\n  -- Nothing here is verified (the leader holds no operator key, D37): whether\n  -- a certificate is the operator's, unexpired and names the node it is for\n  -- is the node's check (`agent_apply_certs`).\n  pfn check_items(r : CtlRelease) : Result((), String) do\n    let delivers = List.any(r.steps, fn s -> match s.action do\n      DoCerts -> true\n      _ -> false\n    end)\n    match List.find(r.certs, fn c -> Result.is_err(NodeCert.from_text(c.cert))) do\n      Some(c) -> Err(\"cert for \" ++ c.node ++ \": not a certificate\")\n      None ->\n        match List.find(r.revokes, fn t -> Result.is_err(NodeCert.revocation_from_text(t))) do\n          Some(_) -> Err(\"revoke: not a revocation token\")\n          None ->\n            match dup_cert(r.certs) do\n              Some(n) -> Err(\"cert: node \" ++ n ++ \" is given two certificates\")\n              None ->\n                if (not(List.is_empty(r.certs)) || not(List.is_empty(r.revokes))) && not(delivers) do\n                  Err(\"the release carries certificate items but no `do:certs` step\")\n                else Ok(()) end\n            end\n        end\n    end\n  end\n\n  doc \"\"\"\n  Is the release well formed? A positive `seq`, a `parent`, `env` and\n  `topology`, distinct builds, steps numbered 1..n in order, every\n  `activate(b)` naming a shipped build, a `drain` line for a drain step,\n  every signed `line` naming a step that exists, and certificate and\n  revocation items that decode, one certificate per node, with a `do:certs`\n  step to deliver them.\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.check(rel)\n      Ok(())\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.check({ rel with seq: 0 })\n      Err(\"seq must be positive\")\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.check({ rel with builds: [] })\n      Err(\"step 1: activates build `web`, which the release does not ship\")\n  \"\"\"\n  fn check(r : CtlRelease) : Result((), String) do\n    if r.seq <= 0 do Err(\"seq must be positive\")\n    else if r.parent == \"\" do Err(\"missing parent (use `parent \" ++ no_parent() ++ \"` for the first release)\")\n    else if r.env == \"\" do Err(\"missing env\")\n    else if r.topology == \"\" do Err(\"missing topology\")\n    else if List.is_empty(r.steps) do Err(\"a release needs at least one step\")\n    else match dup_build(r.builds) do\n      Some(b) -> Err(\"build `\" ++ b ++ \"` is given twice\")\n      None ->\n        let n = List.length(r.steps)\n        match check_steps(r, r.steps, 1) do\n          Err(e) -> Err(e)\n          Ok(_) ->\n            match List.find(r.lines, fn l -> l.step < 1 || l.step > n) do\n              Some(l) -> Err(\"line for step \" ++ int_to_string(l.step) ++ \", which does not exist\")\n              None -> check_items(r)\n            end\n        end\n    end end end end end end\n  end\n\n  -- \u2500\u2500 serialising, identity, signature \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn show_hosts(h : CtlHosts) : String do\n    match h do\n      HostsCanary(n) -> \"canary(\" ++ int_to_string(n) ++ \")\"\n      HostsRest -> \"rest\"\n      HostsAll -> \"all\"\n    end\n  end\n\n  doc \"\"\"\n  The action as the release and the wire write it: `activate(web)`, `topology`, `drain`, `certs`.\n\n  ## Examples\n\n      march> Control.show_action(Control.DoActivate(\"web\"))\n      \"activate(web)\"\n      march> Control.show_action(Control.DoDrain)\n      \"drain\"\n  \"\"\"\n  fn show_action(a : CtlAction) : String do\n    match a do\n      DoActivate(b) -> \"activate(\" ++ b ++ \")\"\n      DoTopology -> \"topology\"\n      DoDrain -> \"drain\"\n      DoCerts -> \"certs\"\n    end\n  end\n\n  pfn show_gate(g : CtlGate) : String do\n    match g do\n      GateNone -> \"none\"\n      GateHealthy(ms) -> \"healthy(\" ++ show_duration(ms) ++ \")\"\n    end\n  end\n\n  pfn show_step(s : CtlStep) : String do\n    let base = \"step \" ++ int_to_string(s.id) ++ \" pools:\" ++ String.join(s.pools, \",\") ++ \" hosts:\" ++ show_hosts(s.hosts)\n      ++ \" do:\" ++ show_action(s.action) ++ \" gate:\" ++ show_gate(s.gate)\n    if s.batch > 0 do base ++ \" batch:\" ++ int_to_string(s.batch) else base end\n  end\n\n  doc \"\"\"\n  The canonical text the signature covers: the release without its `sig`\n  line, one entry per line, single spaces, a newline after every line. forge\n  signs exactly this, so a document may be laid out any way `parse` accepts\n  and still verify.\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.signed_text(rel)\n      \"release v1\\nseq 1\\nparent none\\nenv prod\\ntopology t1\\nbuild web base:b1 manifest:m1\\nstep 1 pools:web hosts:canary(1) do:activate(web) gate:healthy(30s)\\nstep 2 pools:web hosts:rest do:activate(web) gate:none\\n\"\n  \"\"\"\n  fn signed_text(r : CtlRelease) : String do\n    let head_lines = [\n      \"release v1\",\n      \"seq \" ++ int_to_string(r.seq),\n      \"parent \" ++ r.parent,\n      \"env \" ++ r.env,\n      \"topology \" ++ r.topology\n    ]\n    let builds = List.map(r.builds, fn b -> \"build \" ++ b.name ++ \" base:\" ++ b.base ++ \" manifest:\" ++ b.manifest)\n    let steps = List.map(r.steps, fn s -> show_step(s))\n    let lines = List.map(r.lines, fn l -> \"line \" ++ int_to_string(l.step) ++ \" \" ++ l.text)\n    let certs = List.map(r.certs, fn c -> \"cert \" ++ c.node ++ \" \" ++ c.cert)\n    let revokes = List.map(r.revokes, fn t -> \"revoke \" ++ t)\n    let drain = match r.drain do\n      Some(d) -> [\"drain epoch<=\" ++ int_to_string(d.epoch) ++ \" soft:\" ++ int_to_string(d.soft_ms) ++ \" hard:\" ++ int_to_string(d.hard_ms)]\n      None -> Nil\n    end\n    String.join(List.concat([head_lines, builds, steps, lines, certs, revokes, drain]), \"\\n\") ++ \"\\n\"\n  end\n\n  doc \"\"\"\n  The release document: `signed_text`, then its `sig` line (`sig -` when unsigned).\n  `parse(serialize(r)) == Ok(r)` for a well-formed `r`.\n\n  ## Examples\n\n  Using `rel` from `parse`:\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.serialize(rel)\n      \"release v1\\nseq 1\\nparent none\\nenv prod\\ntopology t1\\nbuild web base:b1 manifest:m1\\nstep 1 pools:web hosts:canary(1) do:activate(web) gate:healthy(30s)\\nstep 2 pools:web hosts:rest do:activate(web) gate:none\\nsig -\\n\"\n  \"\"\"\n  fn serialize(r : CtlRelease) : String do\n    -- Compiled, `(if r.signature == \"\" do \"-\" else r.signature end)` used to\n    -- release the field while `r` still held it, so the next read of the\n    -- release's signature found freed memory (ASAN: heap-use-after-free;\n    -- without ASAN an empty `sig`). Fixed in Perceus; this form is kept.\n    -- specs/progress/2026-10-01-compiled-record-with-projection-sigsegv.md\n    let sig_line = if String.is_empty(r.signature) do \"sig -\\n\" else \"sig \" ++ r.signature ++ \"\\n\" end\n    signed_text(r) ++ sig_line\n  end\n\n  doc \"\"\"\n  The release's content address: sha256 (hex, 64 characters) of `signed_text`. A child\n  names it as its `parent`. The `sig` line is not covered, so signing a release does not\n  change its digest.\n\n      let child = { next with seq: rel.seq + 1, parent: Control.digest(rel) }\n  \"\"\"\n  fn digest(r : CtlRelease) : String do sha256(Bytes.from_string(signed_text(r))) end\n\n  doc \"\"\"\n  Sign [r] with an ed25519 secret key (`ed25519_seed_keypair` form). What forge does; here\n  for tests and tooling. Returns [r] with `signature` set to the signature's hex.\n\n      let kp = ed25519_seed_keypair(seed)\n      let signed = Control.sign(rel, kp)\n  \"\"\"\n  fn sign(r : CtlRelease, sk : Bytes) : CtlRelease do\n    { r with signature: Bytes.to_hex(ed25519_sign(sk, Bytes.from_string(signed_text(r)))) }\n  end\n\n  doc \"\"\"\n  Does [r] carry a valid operator signature for [pubkey]? The leader checks\n  this before storing a release so it never relays junk; the nodes check the\n  signed lines themselves either way (the control plane is not trusted, D37).\n\n  `false` too when the signature is not hex.\n\n      Control.verify(Control.sign(rel, secret), public)   -- true\n      Control.verify(rel, public)                         -- false: unsigned\n  \"\"\"\n  fn verify(r : CtlRelease, pubkey : Bytes) : Bool do\n    match Bytes.from_hex(r.signature) do\n      Ok(sg) -> ed25519_verify(pubkey, Bytes.from_string(signed_text(r)), sg)\n      Err(_) -> false\n    end\n  end\n\n  doc \"\"\"\n  The leader's compare-and-set (design section 9): may [r] replace [head], the\n  newest release held? The first release is accepted whatever its parent. The\n  held release itself is accepted again (a retry). Otherwise `r.seq` must be\n  higher and `r.parent` must be `digest(head)`: the parent chain is enforced by\n  the one writer that sees every release (section 5).\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.accept(None, rel)\n      Ok(())\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.accept(Some(rel), rel)\n      Ok(())\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.accept(Some(rel), { rel with seq: 2, parent: Control.digest(rel) })\n      Ok(())\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.accept(Some(rel), { rel with seq: 2, parent: \"x\" })\n      Err(\"parent mismatch: release 2 does not follow the head 1\")\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> Control.accept(Some({ rel with seq: 5 }), rel)\n      Err(\"stale: release 1 is older than the head 5\")\n  \"\"\"\n  fn accept(head : Option(CtlRelease), r : CtlRelease) : Result((), String) do\n    match head do\n      None -> Ok(())\n      Some(h) ->\n        if r.seq == h.seq && digest(r) == digest(h) do Ok(())\n        else if r.seq == h.seq do Err(\"fork: release \" ++ int_to_string(r.seq) ++ \" is already held with other content\")\n        else if r.seq < h.seq do Err(\"stale: release \" ++ int_to_string(r.seq) ++ \" is older than the head \" ++ int_to_string(h.seq))\n        else if r.parent != digest(h) do Err(\"parent mismatch: release \" ++ int_to_string(r.seq) ++ \" does not follow the head \" ++ int_to_string(h.seq))\n        else Ok(()) end end end end\n    end\n  end\n\n  -- \u2500\u2500 what agents report, and what the leader orders \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- A node in the membership, with the pools it runs.\n  type CtlMember = { node : String, pools : List(String) }\n\n  -- A build a node runs, by the manifest hash it has active.\n  type CtlVersion = { build : String, manifest : String }\n\n  -- The last step a node failed: the release, the step, and why (the reload\n  -- server's answer).\n  type CtlFailure = { seq : Int, step : Int, why : String }\n\n  -- The wire records below are flat: `derive Json` encodes String, Int,\n  -- Float and Bool fields and nothing else reliably (a `List` field fails\n  -- at run time in the interpreter), so lists travel as canonical text and\n  -- the accessors after each type read them back. Their codecs are NOT\n  -- derived here: a `derive Json` in an eagerly loaded module puts its\n  -- `from_json` in scope for every program and makes a user's bare\n  -- `from_json` call ambiguous. The module declaring the protocols derives\n  -- them (see test/session/control_peers.march).\n\n  -- What an Agent reports (design section 6): the newest release `seq` the\n  -- node holds, the builds it runs (`versions_text`), its topology digest,\n  -- the highest epoch it has drained, whether it is healthy, and its last\n  -- failed step (`failed_seq` 0: none). `detail` is the node's raw facts as\n  -- text (its pins, its hot slots, its status file: offers, live sessions per\n  -- protocol fingerprint, drain progress), for `forge` to show; the executor\n  -- never reads it. `pools` is the pools the node runs, space-separated (the\n  -- leader's membership: the executor needs node -> pools). A version whose build is `*` is an artifact the node runs\n  -- that it cannot name a build for (the reload server knows patch artifacts,\n  -- not the release's build names); `reports_state` accepts it for any build.\n  -- `certs` is the node's certificate state (`certs_text`): the serial of the\n  -- certificate it presents and the id of every revocation it knows, what a\n  -- `do:certs` step is done by (step 12b).\n  type AgentReport = {\n    node : String, seq : Int, versions : String, topology : String,\n    drained : Int, healthy : Bool, failed_seq : Int, failed_step : Int, failed_why : String,\n    detail : String, pools : String, certs : String\n  }\n\n  pfn version_text(v : CtlVersion) : String do v.build ++ \"=\" ++ v.manifest end\n\n  doc \"\"\"\n  The canonical text of what a node runs: `build=manifest` words, sorted by build.\n  An empty list gives \"\".\n\n  ## Examples\n\n      march> Control.versions_text([{ build: \"web\", manifest: \"m1\" }, { build: \"api\", manifest: \"m2\" }])\n      \"api=m2 web=m1\"\n      march> Control.versions_text([])\n      \"\"\n  \"\"\"\n  fn versions_text(vs : List(CtlVersion)) : String do\n    String.join(List.map(List.sort_by(vs, fn (a, b) -> a.build < b.build), fn v -> version_text(v)), \" \")\n  end\n\n  doc \"\"\"\n  The builds [rep] runs, read back from its `versions` text; a word with no `=` is skipped.\n\n  ## Examples\n\n  `rep` is reused by the examples further down:\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> List.map(Control.report_versions({ rep with versions: \"api=m2 web=m1\" }), fn v -> v.build)\n      [\"api\", \"web\"]\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.report_versions({ rep with versions: \"\" })\n      []\n  \"\"\"\n  fn report_versions(rep : AgentReport) : List(CtlVersion) do\n    List.filter_map(words(rep.versions), fn w ->\n      match String.split_first(w, \"=\") do\n        Some((b, m)) -> Some({ build: b, manifest: m })\n        None -> None\n      end)\n  end\n\n  doc \"\"\"\n  A node's certificate state as it reports it (`AgentReport.certs`):\n  `cert:<serial>` for the certificate it presents (absent on a shared-secret\n  node), then `rev:<id>` for every revocation it knows (`NodeCert.revocation_id`).\n\n      Control.certs_text(Some(my_cert), revs)   -- \"cert:<serial> rev:<id> ...\"\n\n  ## Examples\n\n      march> Control.certs_text(None, [])\n      \"\"\n  \"\"\"\n  fn certs_text(own : Option(NodeCert.Cert), revs : List(NodeCert.Revocation)) : String do\n    let mine = match own do\n      Some(c) -> [\"cert:\" ++ c.serial]\n      None -> Nil\n    end\n    String.join(List.append(mine, List.map(revs, fn r -> \"rev:\" ++ NodeCert.revocation_id(r))), \" \")\n  end\n\n  doc \"\"\"\n  The serial of the certificate [rep]'s node presents (\"\" when it reports none).\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.report_serial(rep)\n      \"42\"\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.report_serial({ rep with certs: \"\" })\n      \"\"\n  \"\"\"\n  fn report_serial(rep : AgentReport) : String do\n    match first_some(words(rep.certs), fn w -> field(w, \"cert\")) do\n      Some(s) -> s\n      None -> \"\"\n    end\n  end\n\n  doc \"\"\"\n  The last step [rep]'s node failed, if any (`failed_seq` 0 means none).\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.report_failure(rep)\n      None\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Option.map(Control.report_failure({ rep with failed_seq: 1, failed_step: 2, failed_why: \"refused\" }), fn f -> f.why)\n      Some(\"refused\")\n  \"\"\"\n  fn report_failure(rep : AgentReport) : Option(CtlFailure) do\n    if rep.failed_seq == 0 do None\n    else Some({ seq: rep.failed_seq, step: rep.failed_step, why: rep.failed_why }) end\n  end\n\n  doc \"\"\"\n  [rep] with its failure set to [f].\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let res = Control.with_failure(rep, { seq: 1, step: 2, why: \"refused\" })\n      march> res.failed_step\n      2\n  \"\"\"\n  fn with_failure(rep : AgentReport, f : CtlFailure) : AgentReport do\n    { rep with failed_seq: f.seq, failed_step: f.step, failed_why: f.why }\n  end\n\n  -- An order for one node to take one step (design section 7): the release\n  -- and step, the action (`show_action`), the end state it must report\n  -- (`want`: a manifest hash, the topology digest, or the drain epoch), the\n  -- artifact hashes it needs (space-separated), and the signed lines to relay\n  -- (newline-separated). Hashes, never bytes.\n  type StepOrder = {\n    seq : Int, release : String, step : Int, node : String, action : String,\n    want : String, artifacts : String, lines : String\n  }\n  derive Eq for StepOrder\n\n  doc \"\"\"\n  The artifact hashes [o] needs.\n\n  ## Examples\n\n  `ord` is reused by the examples further down:\n\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> Control.order_artifacts(ord)\n      [\"m1\"]\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> Control.order_artifacts({ ord with artifacts: \"\" })\n      []\n  \"\"\"\n  fn order_artifacts(o : StepOrder) : List(String) do words(o.artifacts) end\n\n  doc \"\"\"\n  The signed lines [o] relays, in order; blank lines are dropped.\n\n  ## Examples\n\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> Control.order_lines({ ord with lines: \"L1\\n\\nL2\" })\n      [\"L1\", \"L2\"]\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> Control.order_lines(ord)\n      []\n  \"\"\"\n  fn order_lines(o : StepOrder) : List(String) do\n    List.filter(String.split(o.lines, \"\\n\"), fn l -> l != \"\")\n  end\n\n  -- The Agent's answer to a `StepOrder`.\n  type StepResult = { seq : Int, step : Int, node : String, ok : Bool, detail : String }\n\n  -- A leader's observation of a node: its last report, and the leader-clock\n  -- time since which it has been healthy in that state.\n  type CtlObs = { report : AgentReport, healthy_since : Option(Int) }\n\n  pfn same_state(a : AgentReport, b : AgentReport) : Bool do\n    a.versions == b.versions && a.topology == b.topology && a.drained == b.drained\n  end\n\n  pfn obs_of(obs : List(CtlObs), node : String) : Option(CtlObs) do\n    List.find(obs, fn o -> o.report.node == node)\n  end\n\n  doc \"\"\"\n  Record [rep] at leader time [now]. A node's healthy window starts when the\n  leader first sees it healthy in its current state, and restarts when the\n  state changes or the node reports unhealthy. The window is the leader's own,\n  so a new leader restarts every window: conservative (design section 4).\n\n  ## Examples\n\n  `obs0` (node \"a\" healthy since t=1000) is reused by the examples further down:\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let obs0 = Control.observe([], rep, 1000)\n      march> List.map(Control.observe(obs0, rep, 5000), fn o -> o.healthy_since)\n      [Some(1000)]\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let obs0 = Control.observe([], rep, 1000)\n      march> List.map(Control.observe(obs0, { rep with versions: \"web=m2\" }, 5000), fn o -> o.healthy_since)\n      [Some(5000)]\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let obs0 = Control.observe([], rep, 1000)\n      march> List.map(Control.observe(obs0, { rep with healthy: false }, 5000), fn o -> o.healthy_since)\n      [None]\n  \"\"\"\n  fn observe(obs : List(CtlObs), rep : AgentReport, now : Int) : List(CtlObs) do\n    let since = if not(rep.healthy) do None\n      else match obs_of(obs, rep.node) do\n        Some(o) -> match o.healthy_since do\n          Some(t) -> if same_state(o.report, rep) do Some(t) else Some(now) end\n          None -> Some(now)\n        end\n        None -> Some(now)\n      end end\n    Cons({ report: rep, healthy_since: since }, List.filter(obs, fn o -> o.report.node != rep.node))\n  end\n\n  -- \u2500\u2500 the executor \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- One pass's verdict.\n  --\n  --   Apply(step, orders)     step `step` is the first not done; send these\n  --                           orders (possibly none, when every remaining node\n  --                           already has one in flight or the batch is full).\n  --   Wait(step, why)         step `step` is done on its nodes and its gate\n  --                           has not passed yet.\n  --   Halted(step, node, why) the release stops here and is reported. The\n  --                           executor never rolls back.\n  --   Complete                every step is done and every gate passed.\n  --   Behind(seq)             a node holds a newer release than this one; the\n  --                           leader must fetch it before executing anything.\n  type CtlDecision = RolloutApply(Int, List(StepOrder)) | RolloutWait(Int, String) | RolloutHalted(Int, String, String) | RolloutComplete | RolloutBehind(Int)\n  derive Eq for CtlDecision\n\n  pfn in_pools(m : CtlMember, pools : List(String)) : Bool do\n    List.member(pools, \"*\") || List.any(m.pools, fn p -> List.member(pools, p))\n  end\n\n  doc \"\"\"\n  A step's target nodes: the members in any of its pools (every member for `[\"*\"]`),\n  sorted by node name (the canary is the first).\n\n  ## Examples\n\n  `members`, `step1` and `step2` are reused by the examples further down:\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> let step1 = List.head(rel.steps)\n      march> let step2 = List.nth(rel.steps, 1)\n      march> Control.targets(step1, members)\n      [\"a\", \"b\", \"c\"]\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> let step1 = List.head(rel.steps)\n      march> Control.targets({ step1 with pools: [\"*\"] }, members)\n      [\"a\", \"b\", \"c\", \"db1\"]\n  \"\"\"\n  fn targets(step : CtlStep, members : List(CtlMember)) : List(String) do\n    List.sort_by(List.map(List.filter(members, fn m -> in_pools(m, step.pools)), fn m -> m.node), fn (a, b) -> a < b)\n  end\n\n  pfn same_action(a : CtlAction, b : CtlAction) : Bool do show_action(a) == show_action(b) end\n\n  -- The nodes an earlier step selected, if its action is [a].\n  pfn selected_by(p : (CtlStep, List(String)), a : CtlAction) : List(String) do\n    let (s, ns) = p\n    if same_action(s.action, a) do ns else Nil end\n  end\n\n  doc \"\"\"\n  The nodes [step] applies to, given the selections of the steps before it\n  (`(step, nodes)` pairs): `canary(n)` the first n targets, `all` every target,\n  `rest` the targets no earlier step with the same action selected. Selection\n  depends only on the release and the membership, never on progress, so every\n  leader selects the same canary.\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> let step1 = List.head(rel.steps)\n      march> Control.select(step1, members, [])\n      [\"a\"]\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> let step1 = List.head(rel.steps)\n      march> let step2 = List.nth(rel.steps, 1)\n      march> Control.select(step2, members, [(step1, [\"a\"])])\n      [\"b\", \"c\"]\n  \"\"\"\n  fn select(step : CtlStep, members : List(CtlMember), prior : List((CtlStep, List(String)))) : List(String) do\n    let ts = targets(step, members)\n    match step.hosts do\n      HostsCanary(n) -> List.take(ts, n)\n      HostsAll -> ts\n      HostsRest ->\n        let taken = List.flat_map(prior, fn p -> selected_by(p, step.action))\n        List.filter(ts, fn n -> not(List.member(taken, n)))\n    end\n  end\n\n  doc \"\"\"\n  The end state a node reports once [step] of [r] is done on it (`StepOrder.want`): the\n  build's manifest for `activate`, the topology digest, or the drain epoch. \"\" for a\n  `certs` step (per node: see `want_for`) and for a build or drain the release lacks.\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let step1 = List.head(rel.steps)\n      march> Control.want(rel, step1)\n      \"m1\"\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let step1 = List.head(rel.steps)\n      march> Control.want(rel, { step1 with action: Control.DoTopology })\n      \"t1\"\n  \"\"\"\n  fn want(r : CtlRelease, step : CtlStep) : String do\n    match step.action do\n      DoActivate(b) -> match find_build(r, b) do\n        Some(bd) -> bd.manifest\n        None -> \"\"\n      end\n      DoTopology -> r.topology\n      DoDrain -> match r.drain do\n        Some(d) -> int_to_string(d.epoch)\n        None -> \"\"\n      end\n      -- Per node: see `want_for`.\n      DoCerts -> \"\"\n    end\n  end\n\n  pfn cert_item_for(r : CtlRelease, node : String) : Option(CtlCert) do\n    List.find(r.certs, fn c -> c.node == node)\n  end\n\n  pfn item_serial(c : CtlCert) : String do\n    match NodeCert.from_text(c.cert) do\n      Ok(sc) -> sc.cert.serial\n      Err(_) -> \"\"\n    end\n  end\n\n  pfn revocations_of(r : CtlRelease) : List(NodeCert.Revocation) do\n    List.filter_map(r.revokes, fn t -> match NodeCert.revocation_from_text(t) do\n      Ok(sr) -> Some(sr.rev)\n      Err(_) -> None\n    end)\n  end\n\n  doc \"\"\"\n  The end state [node] reports once [step] of [r] is done on it: `want`, except\n  for a `do:certs` step, whose end state is per node: `cert:<serial>` when the\n  release carries a certificate for [node], and `rev:<id>` for each of its\n  revocations (the words of `certs_text` the node must report).\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let step1 = List.head(rel.steps)\n      march> Control.want_for(rel, step1, \"a\")\n      \"m1\"\n  \"\"\"\n  fn want_for(r : CtlRelease, step : CtlStep, node : String) : String do\n    match step.action do\n      DoCerts ->\n        let mine = match cert_item_for(r, node) do\n          Some(c) -> [\"cert:\" ++ item_serial(c)]\n          None -> Nil\n        end\n        String.join(List.append(mine, List.map(revocations_of(r), fn v -> \"rev:\" ++ NodeCert.revocation_id(v))), \" \")\n      _ -> want(r, step)\n    end\n  end\n\n  doc \"\"\"\n  Does [rep] show the end state [w] of an order with action [action] (`show_action` form)?\n  `activate`: a version of that build (or `*`) with manifest [w]; `topology`: the digest;\n  `drain`: drained at least to epoch [w]; `certs`: every word of [w] among the reported\n  ones. An unknown action is never done.\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.reports_state(rep, \"activate(web)\", \"m1\")\n      true\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.reports_state(rep, \"activate(web)\", \"m2\")\n      false\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.reports_state(rep, \"drain\", \"1\")\n      false\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> Control.reports_state(rep, \"certs\", \"cert:42\")\n      true\n  \"\"\"\n  fn reports_state(rep : AgentReport, action : String, w : String) : Bool do\n    match call_arg(action, \"activate\") do\n      Some(b) -> List.any(report_versions(rep), fn v -> (v.build == b || v.build == \"*\") && v.manifest == w)\n      None ->\n        if action == \"topology\" do rep.topology == w\n        else if action == \"drain\" do\n          match string_to_int(w) do\n            Some(e) -> rep.drained >= e\n            None -> false\n          end\n        else if action == \"certs\" do\n          let have = words(rep.certs)\n          List.all(words(w), fn x -> List.member(have, x))\n        else false end end end\n    end\n  end\n\n  -- Does one of [r]'s revocations revoke [node] itself: every certificate\n  -- of its name, or the one it reports presenting? Such a node is cut off\n  -- by the very step that delivers the revocation (its peers drop its\n  -- links), so it may never report the step done: the step does not wait\n  -- for it.\n  pfn revoked_by(r : CtlRelease, obs : List(CtlObs), node : String) : Bool do\n    let serial = match obs_of(obs, node) do\n      Some(o) -> report_serial(o.report)\n      None -> \"\"\n    end\n    List.any(revocations_of(r), fn v ->\n      if String.is_empty(v.serial) do NodeCert.node_name(v.node) == node\n      else v.serial == serial end)\n  end\n\n  pfn done_on(r : CtlRelease, step : CtlStep, obs : List(CtlObs), node : String) : Bool do\n    let reported = match obs_of(obs, node) do\n      Some(o) -> reports_state(o.report, show_action(step.action), want_for(r, step, node))\n      None -> false\n    end\n    match step.action do\n      DoCerts -> reported || revoked_by(r, obs, node)\n      _ -> reported\n    end\n  end\n\n  doc \"\"\"\n  The order that takes [step] of [r] on [node]: `release` is `digest(r)`, `want` is\n  `want_for`, the artifacts are the build's manifest (activate) or the topology digest\n  (topology), and the lines are the release's signed lines for the step (a `certs`\n  step carries the whole serialized release instead).\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let step1 = List.head(rel.steps)\n      march> let o1 = Control.order(rel, step1, \"a\")\n      march> Control.order_artifacts(o1)\n      [\"m1\"]\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let step1 = List.head(rel.steps)\n      march> let o1 = Control.order(rel, step1, \"a\")\n      march> o1.want\n      \"m1\"\n  \"\"\"\n  fn order(r : CtlRelease, step : CtlStep, node : String) : StepOrder do\n    let artifacts = match step.action do\n      DoActivate(b) -> match find_build(r, b) do\n        Some(bd) -> [bd.manifest]\n        None -> Nil\n      end\n      -- The topology's body is an artifact under its digest: a node applies\n      -- it from its own CAS (the signed TOPOLOGY line's body is not in the release).\n      DoTopology -> [r.topology]\n      _ -> Nil\n    end\n    -- A `do:certs` order carries the whole signed release instead of request\n    -- lines: the node checks the deploy key's signature over it itself, so a\n    -- leader cannot hand it an item the release does not carry (D37).\n    let lines = match step.action do\n      DoCerts -> serialize(r)\n      _ -> String.join(List.map(List.filter(r.lines, fn l -> l.step == step.id), fn l -> l.text), \"\\n\")\n    end\n    { seq: r.seq, release: digest(r), step: step.id, node: node, action: show_action(step.action),\n      want: want_for(r, step, node), artifacts: String.join(artifacts, \" \"), lines: lines }\n  end\n\n  pfn first_some(xs : List(String), f : String -> Option(String)) : Option(String) do\n    match xs do\n      Nil -> None\n      Cons(x, rest) -> match f(x) do\n        Some(v) -> Some(v)\n        None -> first_some(rest, f)\n      end\n    end\n  end\n\n  pfn failed_step(r : CtlRelease, step : CtlStep, obs : List(CtlObs), node : String) : Option(String) do\n    match obs_of(obs, node) do\n      Some(o) -> match report_failure(o.report) do\n        Some(f) -> if f.seq == r.seq && f.step == step.id do Some(f.why) else None end\n        None -> None\n      end\n      None -> None\n    end\n  end\n\n  pfn unhealthy(obs : List(CtlObs), node : String) : Bool do\n    match obs_of(obs, node) do\n      Some(o) -> not(o.report.healthy)\n      None -> false\n    end\n  end\n\n  -- Why [node] has not yet passed a healthy([w]) gate at [now], or None.\n  pfn gate_short(obs : List(CtlObs), w : Int, now : Int, node : String) : Option(String) do\n    match obs_of(obs, node) do\n      Some(o) -> match o.healthy_since do\n        Some(t) ->\n          if now - t >= w do None\n          else Some(node ++ \" healthy for \" ++ int_to_string(now - t) ++ \"ms of \" ++ int_to_string(w) ++ \"ms\") end\n        None -> Some(node ++ \" not yet seen healthy\")\n      end\n      None -> Some(node ++ \" has not reported\")\n    end\n  end\n\n  -- The gate of a step whose nodes are all done: None once it has passed.\n  pfn gate_verdict(step : CtlStep, obs : List(CtlObs), nodes : List(String), now : Int) : Option(CtlDecision) do\n    match step.gate do\n      GateNone -> None\n      GateHealthy(w) ->\n        let gname = \"gate \" ++ show_gate(step.gate)\n        match List.find(nodes, fn n -> unhealthy(obs, n)) do\n          Some(n) -> Some(RolloutHalted(step.id, n, gname ++ \" failed: \" ++ n ++ \" reports unhealthy\"))\n          None ->\n            match first_some(nodes, fn n -> gate_short(obs, w, now, n)) do\n              Some(why) -> Some(RolloutWait(step.id, gname ++ \": \" ++ why))\n              None -> None\n            end\n        end\n    end\n  end\n\n  pfn apply_step(r : CtlRelease, step : CtlStep, pending : List(String), inflight : List(String)) : CtlDecision do\n    let busy = List.filter(pending, fn n -> List.member(inflight, n))\n    let free = List.filter(pending, fn n -> not(List.member(inflight, n)))\n    let room = if step.batch == 0 do List.length(free) else step.batch - List.length(busy) end\n    let go = List.take(free, if room < 0 do 0 else room end)\n    RolloutApply(step.id, List.map(go, fn n -> order(r, step, n)))\n  end\n\n  pfn pass_steps(r : CtlRelease, steps : List(CtlStep), members : List(CtlMember), obs : List(CtlObs), inflight : List(String), now : Int, prior : List((CtlStep, List(String)))) : CtlDecision do\n    match steps do\n      Nil -> RolloutComplete\n      Cons(step, rest) ->\n        let sel = with_item_nodes(r, step, select(step, members, prior))\n        match first_some(sel, fn n -> Option.map(failed_step(r, step, obs, n), fn why -> n ++ \"\\n\" ++ why)) do\n          Some(nw) ->\n            match String.split_first(nw, \"\\n\") do\n              Some((n, why)) -> RolloutHalted(step.id, n, why)\n              None -> RolloutHalted(step.id, nw, \"\")\n            end\n          None ->\n            let pending = List.filter(sel, fn n -> not(done_on(r, step, obs, n)))\n            if pending != Nil do apply_step(r, step, pending, inflight)\n            else\n              match gate_verdict(step, obs, sel, now) do\n                Some(d) -> d\n                None -> pass_steps(r, rest, members, obs, inflight, now, List.append(prior, [(step, sel)]))\n              end\n            end\n        end\n    end\n  end\n\n  -- A `do:certs` step also targets every node a certificate item names,\n  -- member or not: a release that renews a node's certificate is not done\n  -- until that node reports presenting it. (A node the leader has not heard\n  -- from, or no longer hears from, holds the release until it reports; it\n  -- would otherwise be called done without it.)\n  pfn with_item_nodes(r : CtlRelease, step : CtlStep, sel : List(String)) : List(String) do\n    match step.action do\n      DoCerts -> List.append(sel, List.filter(List.map(r.certs, fn c -> c.node), fn n -> not(List.member(sel, n))))\n      _ -> sel\n    end\n  end\n\n  pfn max_seq(obs : List(CtlObs), acc : Int) : Int do\n    match obs do\n      Nil -> acc\n      Cons(o, rest) -> max_seq(rest, if o.report.seq > acc do o.report.seq else acc end)\n    end\n  end\n\n  doc \"\"\"\n  The executor's pass (design section 4), a pure function of the release, the\n  membership, the observations, the nodes with an order in flight, and the\n  leader's clock. Steps run strictly in order: a step's orders go out only\n  once every earlier step is done on its nodes and its gate has passed, and a\n  node is ordered only while it does not report the step's end state and has\n  no order in flight. So no step is skipped and none is applied twice.\n\n  ## Examples\n\n  Node \"a\" is the canary; once it reports `m1` the 30 s gate holds step 2 back:\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> Control.show_decision(Control.pass(rel, members, [], [], 0))\n      \"step 1: apply to [a]\"\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> Control.show_decision(Control.pass(rel, members, [], [\"a\"], 0))\n      \"step 1: apply to []\"\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let obs0 = Control.observe([], rep, 1000)\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> Control.show_decision(Control.pass(rel, members, obs0, [], 2000))\n      \"step 1: waiting, gate healthy(30s): a healthy for 1000ms of 30000ms\"\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let obs0 = Control.observe([], rep, 1000)\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> Control.show_decision(Control.pass(rel, members, obs0, [], 31000))\n      \"step 2: apply to [b, c]\"\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> Control.show_decision(Control.pass(rel, members, Control.observe([], { rep with seq: 4 }, 0), [], 0))\n      \"behind: a node holds release 4\"\n  \"\"\"\n  fn pass(r : CtlRelease, members : List(CtlMember), obs : List(CtlObs), inflight : List(String), now : Int) : CtlDecision do\n    let newest = max_seq(obs, r.seq)\n    if newest > r.seq do RolloutBehind(newest)\n    else pass_steps(r, r.steps, members, obs, inflight, now, Nil) end\n  end\n\n  -- \u2500\u2500 the leader's memory \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- What a leader holds: the newest release, its observations, the nodes with\n  -- an order outstanding, and a halt, which sticks for the release. None of it\n  -- is handed over: a new leader starts from `leader_new()`, the newest\n  -- release it can find, and the agents' next reports.\n  type CtlLeader = { release : Option(CtlRelease), obs : List(CtlObs), inflight : List(String), halted : Option(CtlDecision) }\n\n  doc \"\"\"\n  A leader holding nothing yet.\n\n  ## Examples\n\n      march> let ldr0 = Control.leader_new()\n      march> Option.is_none(ldr0.release)\n      true\n  \"\"\"\n  fn leader_new() : CtlLeader do { release: None, obs: Nil, inflight: Nil, halted: None } end\n\n  doc \"\"\"\n  Offer a release to the leader (`check`, then `accept`'s compare-and-set). A new release\n  clears the halt and the orders in flight; offering the held release again changes nothing.\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let ldr0 = Control.leader_new()\n      march> let ldr1 = Result.unwrap(Control.leader_release(ldr0, rel))\n      march> Control.leader_release(ldr1, { rel with seq: 0 })\n      Err(\"seq must be positive\")\n  \"\"\"\n  fn leader_release(l : CtlLeader, r : CtlRelease) : Result(CtlLeader, String) do\n    let? _ = check(r)\n    let? _ = accept(l.release, r)\n    match l.release do\n      Some(h) -> if h.seq == r.seq do Ok(l) else Ok({ l with release: Some(r), halted: None, inflight: Nil }) end\n      None -> Ok({ l with release: Some(r), halted: None, inflight: Nil })\n    end\n  end\n\n  doc \"\"\"\n  An agent reported: record it; the node's order (if any) is no longer in\n  flight. A failure this leader already knows of for the node is kept even if\n  the report omits it, so a halt cannot be lost to a report sent before the\n  failure; so is the node's `detail` when the report has none (a poll's).\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ldr2 = Control.leader_report(Control.leader_new(), rep, 1000)\n      march> List.length(ldr2.obs)\n      1\n  \"\"\"\n  fn leader_report(l : CtlLeader, rep : AgentReport, now : Int) : CtlLeader do\n    let prior = obs_of(l.obs, rep.node)\n    let merged0 = match (report_failure(rep), prior) do\n      (None, Some(o)) -> match report_failure(o.report) do\n        Some(f) -> with_failure(rep, f)\n        None -> rep\n      end\n      _ -> rep\n    end\n    -- A report without `detail` (a poll's; the hello carries it) keeps the\n    -- detail last reported.\n    let merged = match prior do\n      Some(o) -> if merged0.detail == \"\" && o.report.detail != \"\" do { merged0 with detail: o.report.detail } else merged0 end\n      None -> merged0\n    end\n    { l with obs: observe(l.obs, merged, now), inflight: List.filter(l.inflight, fn n -> n != rep.node) }\n  end\n\n  doc \"\"\"\n  An agent answered an order. A failure is recorded as the node's failed step\n  (so the next pass halts; a new leader re-derives the halt from the agent's\n  own report). The order stays in flight until the node's next report, so it\n  is not sent again on the strength of a stale report.\n\n  A result from a node the leader has no report of changes nothing.\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> let ldr2 = Control.leader_report(Control.leader_new(), rep, 1000)\n      march> let ldr3 = Control.leader_result(Result.unwrap(Control.leader_release(ldr2, rel)), { seq: 1, step: 1, node: \"a\", ok: false, detail: \"ERR refused\" }, 1500)\n      march> Option.map(Tuple.second(Control.leader_pass(ldr3, members, 2000)), Control.show_decision)\n      Some(\"step 1: HALTED on a: ERR refused\")\n  \"\"\"\n  fn leader_result(l : CtlLeader, res : StepResult, now : Int) : CtlLeader do\n    if res.ok do l\n    else\n      let f = { seq: res.seq, step: res.step, why: res.detail }\n      match obs_of(l.obs, res.node) do\n        Some(o) -> { l with obs: observe(l.obs, with_failure(o.report, f), now) }\n        None -> l\n      end\n    end\n  end\n\n  doc \"\"\"\n  Run a pass. The orders it returns are now in flight. A `RolloutHalted` verdict\n  sticks until a new release; `RolloutComplete` and `RolloutWait` hold no state.\n\n  A leader with no release returns `None`.\n\n  ## Examples\n\n      march> let rel = { seq: 1, parent: \"none\", env: \"prod\", topology: \"t1\", builds: [{ name: \"web\", base: \"b1\", manifest: \"m1\" }], steps: [{ id: 1, pools: [\"web\"], hosts: Control.HostsCanary(1), action: Control.DoActivate(\"web\"), gate: Control.GateHealthy(30000), batch: 0 }, { id: 2, pools: [\"web\"], hosts: Control.HostsRest, action: Control.DoActivate(\"web\"), gate: Control.GateNone, batch: 0 }], lines: [], certs: [], revokes: [], drain: None, signature: \"\" }\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> let ldr0 = Control.leader_new()\n      march> let ldr1 = Result.unwrap(Control.leader_release(ldr0, rel))\n      march> Option.map(Tuple.second(Control.leader_pass(ldr1, members, 0)), Control.show_decision)\n      Some(\"step 1: apply to [a]\")\n      march> let members = [{ node: \"b\", pools: [\"web\"] }, { node: \"a\", pools: [\"web\"] }, { node: \"c\", pools: [\"web\"] }, { node: \"db1\", pools: [\"db\"] }]\n      march> let ldr0 = Control.leader_new()\n      march> Tuple.second(Control.leader_pass(ldr0, members, 0))\n      None\n  \"\"\"\n  fn leader_pass(l : CtlLeader, members : List(CtlMember), now : Int) : (CtlLeader, Option(CtlDecision)) do\n    match l.halted do\n      Some(h) -> (l, Some(h))\n      None ->\n        match l.release do\n          None -> (l, None)\n          Some(r) ->\n            let d = pass(r, members, l.obs, l.inflight, now)\n            match d do\n              RolloutApply(_, orders) -> ({ l with inflight: List.append(l.inflight, List.map(orders, fn o -> o.node)) }, Some(d))\n              RolloutHalted(_, _, _) -> ({ l with halted: Some(d) }, Some(d))\n              _ -> (l, Some(d))\n            end\n        end\n    end\n  end\n\n  doc \"\"\"\n  The decision as one line, for status output and logs.\n\n  ## Examples\n\n      march> Control.show_decision(Control.RolloutComplete)\n      \"complete\"\n      march> Control.show_decision(Control.RolloutHalted(2, \"a\", \"ERR refused\"))\n      \"step 2: HALTED on a: ERR refused\"\n  \"\"\"\n  fn show_decision(d : CtlDecision) : String do\n    match d do\n      RolloutApply(s, os) -> \"step \" ++ int_to_string(s) ++ \": apply to [\" ++ String.join(List.map(os, fn o -> o.node), \", \") ++ \"]\"\n      RolloutWait(s, why) -> \"step \" ++ int_to_string(s) ++ \": waiting, \" ++ why\n      RolloutHalted(s, n, why) -> \"step \" ++ int_to_string(s) ++ \": HALTED on \" ++ n ++ \": \" ++ why\n      RolloutComplete -> \"complete\"\n      RolloutBehind(s) -> \"behind: a node holds release \" ++ int_to_string(s)\n    end\n  end\n\n  -- \u2500\u2500 the Agent's side \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- How an Agent reaches its node. `report` reads the node's state, `has`\n  -- answers `CAS_CHECK` for a hash, and `request` runs one signed request\n  -- line through the reload server and returns its answer (`OK ...` or\n  -- `ERR ...`). The real Agent builds this over the `reload_request` builtin\n  -- (design section 6, not built yet); tests build it over a simulated node.\n  type AgentOps = { report : () -> AgentReport, has : String -> Bool, request : String -> String }\n\n  doc \"\"\"\n  The artifacts of [o] the node does not hold yet (to fetch over `CtlFetch` before applying).\n\n  ## Examples\n\n  `ops` simulates a node: it reports `rep`, holds artifact `m1`, and accepts every line.\n  It is reused by the examples further down:\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> Control.missing(ops, ord)\n      []\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> Control.missing({ ops with has: fn h -> false }, ord)\n      [\"m1\"]\n  \"\"\"\n  fn missing(ops : AgentOps, o : StepOrder) : List(String) do\n    List.filter(order_artifacts(o), fn h -> not(ops.has(h)))\n  end\n\n  pfn relay(ops : AgentOps, lines : List(String)) : Option(String) do\n    match lines do\n      Nil -> None\n      Cons(l, rest) ->\n        let resp = ops.request(l)\n        if String.starts_with(resp, \"OK\") do relay(ops, rest) else Some(resp) end\n    end\n  end\n\n  pfn result_of(o : StepOrder, ok : Bool, detail : String) : StepResult do\n    { seq: o.seq, step: o.step, node: o.node, ok: ok, detail: detail }\n  end\n\n  doc \"\"\"\n  Apply one order on this node. Idempotent: a node that already reports the\n  order's end state answers ok without touching the reload server, so an\n  order a new leader sends again is harmless. Missing artifacts or a refused\n  line answer not-ok with the reason, which halts the release. A topology\n  step the reload server took is given a few placement ticks for the node to\n  report it (`agent_apply_within`).\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> let res = Control.agent_apply(ops, ord)\n      march> res.detail\n      \"already applied\"\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> let res = Control.agent_apply({ ops with has: fn h -> false }, { ord with want: \"m2\" })\n      march> res.detail\n      \"missing artifacts: m1\"\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> let res = Control.agent_apply({ ops with request: fn l -> \"ERR bad signature\" }, { ord with want: \"m2\", lines: \"SEQ 1 x\" })\n      march> res.detail\n      \"ERR bad signature\"\n  \"\"\"\n  fn agent_apply(ops : AgentOps, o : StepOrder) : StepResult do agent_apply_ticked(ops, o, 200) end\n\n  doc \"\"\"\n  `agent_apply` on a node whose placement loop ticks every [tick_ms]\n  (`MARCH_PLACEMENT_TICK_MS`; `agent_apply` assumes its default, 200): a\n  topology step waits `topology_wait_ms(tick_ms)` for the node to report it.\n\n  A [tick_ms] below 1 is taken as 1.\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> let res = Control.agent_apply_ticked(ops, ord, 50)\n      march> res.ok\n      true\n  \"\"\"\n  fn agent_apply_ticked(ops : AgentOps, o : StepOrder, tick_ms : Int) : StepResult do\n    let tick = if tick_ms < 1 do 1 else tick_ms end\n    agent_apply_within(ops, o, topology_wait_ms(tick), if tick < 100 do tick else 100 end)\n  end\n\n  doc \"\"\"\n  How long a topology step waits for the node's placement loop to apply a\n  digest the reload server already took, given the loop's tick [tick_ms]:\n  ten ticks, at least two seconds (a loaded host delays a tick), at most a\n  minute.\n\n  ## Examples\n\n      march> Control.topology_wait_ms(200)\n      2000\n      march> Control.topology_wait_ms(500)\n      5000\n      march> Control.topology_wait_ms(10000)\n      60000\n  \"\"\"\n  fn topology_wait_ms(tick_ms : Int) : Int do\n    let w = tick_ms * 10\n    if w < 2000 do 2000 else if w > 60000 do 60000 else w end end\n  end\n\n  doc \"\"\"\n  `agent_apply`, waiting at most [wait_ms] (polling every [poll_ms]) for a\n  topology step's end state. The reload server takes a `TOPOLOGY` line at\n  once, but the node reports the digest only once its placement loop has\n  re-read the file, on its next tick (`MARCH_PLACEMENT_TICK_MS`): until then\n  the step is pending, not failed. Every other step is checked once.\n\n  ## Examples\n\n  Every line accepted, but the node never reports the new manifest:\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> let res = Control.agent_apply_within(ops, { ord with want: \"m2\" }, 0, 10)\n      march> res.detail\n      \"the node accepted every line but does not report activate(web) at m2\"\n  \"\"\"\n  fn agent_apply_within(ops : AgentOps, o : StepOrder, wait_ms : Int, poll_ms : Int) : StepResult do\n    if reports_state(ops.report(), o.action, o.want) do result_of(o, true, \"already applied\")\n    else\n      let ms = missing(ops, o)\n      if ms != Nil do result_of(o, false, \"missing artifacts: \" ++ String.join(ms, \" \"))\n      else match relay(ops, order_lines(o)) do\n        Some(err) -> result_of(o, false, err)\n        None ->\n          let left = if o.action == \"topology\" do wait_ms else 0 end\n          if await_state(ops, o, left, if poll_ms < 1 do 1 else poll_ms end) do result_of(o, true, \"applied\")\n          else result_of(o, false, \"the node accepted every line but does not report \" ++ o.action ++ \" at \" ++ o.want) end\n      end end\n    end\n  end\n\n  -- Does the node report [o]'s end state now, or within [left_ms]?\n  pfn await_state(ops : AgentOps, o : StepOrder, left_ms : Int, poll_ms : Int) : Bool do\n    if reports_state(ops.report(), o.action, o.want) do true\n    else if left_ms <= 0 do false\n    else\n      sleep_ms(poll_ms)\n      await_state(ops, o, left_ms - poll_ms, poll_ms)\n    end end\n  end\n\n  -- \u2500\u2500 the real Agent (design section 6) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  --\n  -- `AgentOps` over the node's own reload server, through the stdlib-only\n  -- `reload_request` builtin: the same C dispatch the socket runs, so the\n  -- signature checks, the release sequence and the audit are the socket's.\n  -- The Agent adds no authority: it relays operator-signed lines.\n\n  doc \"\"\"\n  The reload server's answer to [line] (or lines: the request is a stream, a body verb's\n  bytes follow the first newline). Goes through the stdlib-only `reload_request` builtin.\n\n      Control.relay_line(\"NODE_STATE\")\n  \"\"\"\n  fn relay_line(line : String) : String do reload_request(line) end\n\n  doc \"\"\"\n  The value of `key:value` among the words of [line] (\"\" when absent).\n\n  ## Examples\n\n      march> Control.state_field(\"STATE head:3 drained:1 topology:t1\", \"head\")\n      \"3\"\n      march> Control.state_field(\"STATE head:3\", \"topology\")\n      \"\"\n  \"\"\"\n  fn state_field(line : String, key : String) : String do\n    match first_some(words(line), fn w -> field(w, key)) do\n      Some(v) -> v\n      None -> \"\"\n    end\n  end\n\n  doc \"\"\"\n  The non-empty lines of a reload-server answer.\n\n  ## Examples\n\n      march> Control.answer_lines(\"OK\\n\\nSTATE head:3\\n\")\n      [\"OK\", \"STATE head:3\"]\n  \"\"\"\n  fn answer_lines(resp : String) : List(String) do\n    List.filter(String.split(resp, \"\\n\"), fn l -> l != \"\")\n  end\n\n  doc \"\"\"\n  The `STATE` line of a `NODE_STATE` answer (\"\" when absent).\n\n  ## Examples\n\n      march> Control.state_line([\"PIN 1\", \"STATE head:3 drained:1\"])\n      \"STATE head:3 drained:1\"\n      march> Control.state_line([])\n      \"\"\n  \"\"\"\n  fn state_line(lines : List(String)) : String do\n    match List.find(lines, fn l -> String.starts_with(l, \"STATE \")) do\n      Some(l) -> l\n      None -> \"\"\n    end\n  end\n\n  pfn artifact_of(l : String) : Option(CtlVersion) do\n    if String.starts_with(l, \"ARTIFACT \") do Some({ build: \"*\", manifest: String.trim(String.slice(l, 9, String.byte_size(l) - 9)) })\n    else None end\n  end\n\n  doc \"\"\"\n  What the node reports without the status file: the reload server's `NODE_STATE` and\n  `PINS`, and [failure] (the last step this agent failed, `seq step why`, or \\\"\\\").\n  Not `VERSIONS_DETAIL`: one line per function (about 14,000 in a small app),\n  on every poll, cost a node gigabytes within a minute. The patch artifacts in\n  effect (`NODE_STATE`) are what the executor needs, and an operator reads the\n  per-function view through the control API (`VERSIONS_DETAIL` passes through).\n\n      let rep = Control.reload_report(\"node-a\", \"web\", status_text, true, \"\", certs)\n  \"\"\"\n  fn reload_report(name : String, pools : String, status : String, applied : Bool, failure : String, certs : String) : AgentReport do\n    let st = answer_lines(relay_line(\"NODE_STATE\"))\n    let head = state_line(st)\n    let seq = match string_to_int(state_field(head, \"head\")) do\n      Some(n) -> n\n      None -> 0\n    end\n    let drained = match string_to_int(state_field(head, \"drained\")) do\n      Some(n) -> n\n      None -> 0\n    end\n    let topo = state_field(head, \"topology\")\n    let fparts = String.split(failure, \" \")\n    let fseq = match List.head_opt(fparts) do\n      Some(x) -> match string_to_int(x) do\n        Some(n) -> n\n        None -> 0\n      end\n      None -> 0\n    end\n    let fstep = match List.head_opt(List.drop(fparts, 1)) do\n      Some(x) -> match string_to_int(x) do\n        Some(n) -> n\n        None -> 0\n      end\n      None -> 0\n    end\n    let fwhy = String.join(List.drop(fparts, 2), \" \")\n    let detail = \"pins\\n\" ++ String.join(answer_lines(relay_line(\"PINS\")), \"\\n\") ++ \"\\nstatus\\n\" ++ status\n    { node: name, seq: seq, versions: versions_text(List.filter_map(st, fn l -> artifact_of(l))),\n      topology: if applied do topo else \"-\" end, drained: drained, healthy: head != \"\",\n      failed_seq: fseq, failed_step: fstep, failed_why: fwhy, detail: detail, pools: pools, certs: certs }\n  end\n\n  doc \"\"\"\n  The Agent's ops over this node's reload server. [status] is called for each report: the\n  topology status text (`Topology.status_text`), and whether the verified topology\n  is the one the node applied. [memory] keeps the last failed step (see\n  `agent_apply_recording`). [certs] is the node's certificate state\n  (`certs_text`). `has` is the artifact's presence in the CAS\n  (a `base:` in the release is informational: the base image is not an artifact).\n\n      let mem = Vault.new(\"agent\")\n      let ops = Control.real_ops(\"node-a\", \"web\", status, certs, mem)\n      Control.agent_apply_recording(ops, mem, order, 200)\n  \"\"\"\n  fn real_ops(name : String, pools : String, status : () -> (String, Bool), certs : () -> String, memory : Vault(String)) : AgentOps do\n    { report: fn ->\n        let (text, applied) = status()\n        reload_report(name, pools, text, applied, Vault.get_or(memory, \"failure\", \"\"), certs()),\n      has: fn h -> String.starts_with(relay_line(\"CAS_CHECK \" ++ h), \"PRESENT\"),\n      request: fn line -> String.trim(relay_line(line)) }\n  end\n\n  doc \"\"\"\n  `agent_apply_ticked` (on a node whose placement loop ticks every [tick_ms]),\n  remembering a failure in [memory] so the node's next report carries it\n  (a new leader re-derives the halt from it) and forgetting it once a later order succeeds.\n  A batch left half-staged by an earlier failed step is rolled back first.\n\n  ## Examples\n\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> let mem = Vault.new(\"doc_control_memory\")\n      march> let res = Control.agent_apply_recording({ ops with has: fn h -> false }, mem, { ord with want: \"m2\" }, 200)\n      march> res.ok\n      false\n      march> let rep = { node: \"a\", seq: 1, versions: \"web=m1\", topology: \"t1\", drained: 0, healthy: true, failed_seq: 0, failed_step: 0, failed_why: \"\", detail: \"\", pools: \"web\", certs: \"cert:42 rev:r7\" }\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> let ops = { report: fn -> rep, has: fn h -> h == \"m1\", request: fn l -> \"OK\" }\n      march> let mem = Vault.new(\"doc_control_memory\")\n      march> let res = Control.agent_apply_recording(ops, mem, ord, 200)\n      march> res.ok\n      true\n\n  After the failure `mem` holds `\"failure\"` = `\"1 1 missing artifacts: m1\"` (`seq step\n  why`); the success that follows removes it.\n  \"\"\"\n  fn agent_apply_recording(ops : AgentOps, memory : Vault(String), o : StepOrder, tick_ms : Int) : StepResult do\n    let _ = ops.request(\"ROLLBACK_BATCH\")\n    remember(memory, agent_apply_ticked(ops, o, tick_ms))\n  end\n\n  -- Record [res] in [memory]: a failure until a later order succeeds.\n  pfn remember(memory : Vault(String), res : StepResult) : StepResult do\n    if res.ok do Vault.drop(memory, \"failure\")\n    else Vault.set(memory, \"failure\", int_to_string(res.seq) ++ \" \" ++ int_to_string(res.step) ++ \" \" ++ res.detail) end\n    res\n  end\n\n  -- \u2500\u2500 certificates and revocations (step 12b) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  --\n  -- A `do:certs` order carries its whole release (`order`). The node checks\n  -- both signatures itself, so a compromised leader can forge neither (D37):\n  -- the deploy key's over the release (`deploy_key`, the key the node's\n  -- reload server trusts), and the operator key's over each certificate and\n  -- revocation (`replace` and `revoke`, which are `ClusterNode.replace_cert`\n  -- and `ClusterNode.revoke`). Issuance stays with the operator (D39).\n\n  -- How an Agent reaches its node's certificate state. [name] is this node's\n  -- name, [deploy_key] the deploy public key releases verify under,\n  -- [serial] the serial of the certificate it presents now (\"\" when none),\n  -- [replace] takes a certificate's text form (`ClusterNode.replace_cert`,\n  -- keeping the node's key) and [revoke] a revocation token\n  -- (`ClusterNode.revoke`, which gossips it on). [floor] is the newest\n  -- release seq this node has taken anything from: an older release is\n  -- refused, so a replayed release cannot put back a certificate a later one\n  -- replaced.\n  type CertOps = {\n    name : String, deploy_key : Bytes, serial : () -> String,\n    replace : String -> Result(String, String), revoke : String -> Result((), String), floor : () -> Int\n  }\n\n  -- The release a `do:certs` order carries, once it is the one the order\n  -- names and the deploy key signed it.\n  pfn order_release(c : CertOps, o : StepOrder) : Result(CtlRelease, String) do\n    match parse(o.lines) do\n      Err(e) -> Err(\"the order's release does not parse: \" ++ e)\n      Ok(r) ->\n        if not(verify(r, c.deploy_key)) do Err(\"the order's release is not signed by the deploy key\")\n        else if digest(r) != o.release || r.seq != o.seq do Err(\"the order's release is not the release it names\")\n        else if r.seq < c.floor() do Err(\"stale: release \" ++ int_to_string(r.seq) ++ \" is older than release \" ++ int_to_string(c.floor()) ++ \", which this node has taken\")\n        else Ok(r) end end end\n    end\n  end\n\n  -- This node's certificate item, applied: refused unless it names this\n  -- node (as the item's target and in the certificate itself); a no-op when\n  -- the node already presents it. The operator's signature, the expiry, the\n  -- key and revocation are `replace`'s checks (`ClusterNode.replace_cert`).\n  pfn apply_cert(c : CertOps, item : CtlCert) : Result(String, String) do\n    match NodeCert.from_text(item.cert) do\n      Err(e) -> Err(\"the certificate for \" ++ c.name ++ \": \" ++ e)\n      Ok(sc) ->\n        let named = NodeCert.node_name(sc.cert.node)\n        if named != c.name do Err(\"the certificate for \" ++ c.name ++ \" names \" ++ sc.cert.node ++ \", not this node\")\n        else if sc.cert.serial == c.serial() do Ok(\"certificate \" ++ sc.cert.serial ++ \" already in use\")\n        else match c.replace(item.cert) do\n          Ok(serial) -> Ok(\"certificate \" ++ serial ++ \" in use\")\n          Err(e) -> Err(e)\n        end end end\n    end\n  end\n\n  pfn apply_revokes(c : CertOps, ts : List(String), n : Int) : Result(Int, String) do\n    match ts do\n      Nil -> Ok(n)\n      Cons(t, rest) ->\n        match c.revoke(t) do\n          Ok(_) -> apply_revokes(c, rest, n + 1)\n          Err(e) -> Err(e)\n        end\n    end\n  end\n\n  doc \"\"\"\n  Apply a `do:certs` order on this node (step 12b): check the release it\n  carries (the deploy key's signature, that it is the release the order names,\n  not older than one this node took from), then take the certificate item for\n  THIS node, if there is one (`apply_cert`; items for other nodes are not\n  this node's to apply), then every revocation (`ClusterNode.revoke` keeps a\n  known one once, so a revocation already gossiped here is a no-op). Idempotent:\n  a certificate already in use and a revocation already known change nothing.\n  Any refusal answers not-ok with the reason, which halts the release.\n\n      match Control.agent_apply_certs(cert_ops, order) do\n        r -> if r.ok do () else println(\"refused: \" ++ r.detail) end\n      end\n  \"\"\"\n  fn agent_apply_certs(c : CertOps, o : StepOrder) : StepResult do\n    match order_release(c, o) do\n      Err(e) -> result_of(o, false, e)\n      Ok(r) ->\n        let mine = match cert_item_for(r, c.name) do\n          Some(item) -> apply_cert(c, item)\n          None -> Ok(\"\")\n        end\n        match mine do\n          Err(e) -> result_of(o, false, e)\n          Ok(said) ->\n            match apply_revokes(c, r.revokes, 0) do\n              Err(e) -> result_of(o, false, e)\n              Ok(n) ->\n                let revs = if n == 0 do \"\" else int_to_string(n) ++ \" revocation(s) known\" end\n                let parts = List.filter([said, revs], fn x -> x != \"\")\n                result_of(o, true, if parts == Nil do \"nothing for this node\" else String.join(parts, \"; \") end)\n            end\n        end\n    end\n  end\n\n  doc \"\"\"\n  `agent_apply_certs`, remembering a failure in [memory] like\n  `agent_apply_recording`, and the release's seq once it succeeds: the floor\n  below which this node refuses certificate releases (`CertOps.floor` should\n  read it back with `cert_floor`).\n\n      let res = Control.agent_apply_certs_recording(cert_ops, mem, order)\n      Control.cert_floor(mem)    -- order.seq once res.ok\n  \"\"\"\n  fn agent_apply_certs_recording(c : CertOps, memory : Vault(String), o : StepOrder) : StepResult do\n    let res = remember(memory, agent_apply_certs(c, o))\n    if res.ok && o.seq > cert_floor(memory) do Vault.set(memory, \"cert_floor\", int_to_string(o.seq)) else () end\n    res\n  end\n\n  doc \"\"\"\n  The newest release seq this agent has taken certificates or revocations from (0: none),\n  as `agent_apply_certs_recording` keeps it. An unreadable entry also reads 0.\n\n  ## Examples\n\n      march> Control.cert_floor(Vault.new(\"doc_control_cert_floor\"))\n      0\n  \"\"\"\n  fn cert_floor(memory : Vault(String)) : Int do\n    match string_to_int(Vault.get_or(memory, \"cert_floor\", \"0\")) do\n      Some(n) -> n\n      None -> 0\n    end\n  end\n\n  -- \u2500\u2500 what the protocols carry (design section 7) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  --\n  -- The `Ctl` and `CtlFetch` protocols themselves are not declared here yet:\n  -- their canonical declaration and role bodies live in\n  -- test/session/control_peers.march, and the wiring splices them into the\n  -- generated topology `main`. A stdlib protocol works since 2026-10-03\n  -- (specs/progress/2026-10-03-endpoints-protocol-in-nested-module.md); the\n  -- move is specs/todos/2026-09-28-dd-step12a-control-wiring.md. Everything\n  -- the roles need is here.\n\n  -- A chunk of an artifact: its offset, the bytes as hex, and whether it is\n  -- the last.\n  type CtlChunk = { offset : Int, data : String, last : Bool }\n\n  doc \"\"\"\n  Split [hex] (an artifact as hex) into chunks of [size] hex characters, offsets counted in\n  characters; an artifact of at most [size] characters (including an empty one) is one last\n  chunk.\n\n  ## Examples\n\n      march> List.map(Control.chunks(\"abcdef\", 4), fn c -> c.data)\n      [\"abcd\", \"ef\"]\n      march> List.map(Control.chunks(\"abcdef\", 4), fn c -> c.offset)\n      [0, 4]\n      march> List.map(Control.chunks(\"\", 4), fn c -> c.last)\n      [true]\n  \"\"\"\n  fn chunks(hex : String, size : Int) : List(CtlChunk) do\n    let n = String.byte_size(hex)\n    if n <= size do [{ offset: 0, data: hex, last: true }]\n    else chunks_from(hex, size, 0, n) end\n  end\n\n  pfn chunks_from(hex : String, size : Int, off : Int, n : Int) : List(CtlChunk) do\n    if off + size >= n do [{ offset: off, data: String.slice(hex, off, n - off), last: true }]\n    else Cons({ offset: off, data: String.slice(hex, off, size), last: false }, chunks_from(hex, size, off + size, n)) end\n  end\n\n  -- What to do next in one agent's `Ctl` session: send an order, poll for a\n  -- report, or end the session.\n  type CtlNext = NextOrder(StepOrder) | NextPoll | NextBye(String)\n\n  -- What the leader's side of one agent's session asks of the executor.\n  -- `report` takes a report (the hello, and every poll's answer), `stepped`\n  -- an order's result, `next(node)` says what to do next with that node's\n  -- session, and `head()` is the newest release seq the leader holds.\n  type ControlOps = { report : AgentReport -> (), stepped : StepResult -> (), next : String -> CtlNext, head : () -> Int }\n\n  -- \u2500\u2500 the leader's audit log (design section 9) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  --\n  -- One JSON object per line, like a node's audit log (runtime/march_reload.c):\n  -- `ts` (ms), `type`, `leader` (the node that wrote it), then the fields of\n  -- that type. `release`: a release offered to the leader, with `result` \"ok\"\n  -- or why it was refused. `order`: a step ordered on a node. `step`: a node's\n  -- answer to an order. `halt` and `complete`: the release's end. The\n  -- candidates hold the file; these build its lines.\n\n  pfn audit_json(ts : Int, kind : String, leader : String, fields : List((String, Json.JsonValue))) : String do\n    Json.to_string(Json.Object(Cons((\"ts\", Json.Number(int_to_float(ts))), Cons((\"type\", Json.Str(kind)), Cons((\"leader\", Json.Str(leader)), fields))))) ++ \"\\n\"\n  end\n\n  doc \"\"\"\n  The `result` of a release the leader refused, from its reason: `err_stale`,\n  `err_fork`, `err_parent` (the compare-and-set on `parent`), or `err_invalid`\n  (the release does not check).\n\n  ## Examples\n\n      march> Control.audit_refusal(\"stale: release 1 is older than the head 2\")\n      \"err_stale\"\n      march> Control.audit_refusal(\"missing env\")\n      \"err_invalid\"\n  \"\"\"\n  fn audit_refusal(why : String) : String do\n    if String.starts_with(why, \"stale\") do \"err_stale\"\n    else if String.starts_with(why, \"fork\") do \"err_fork\"\n    else if String.starts_with(why, \"parent mismatch\") do \"err_parent\"\n    else \"err_invalid\" end end end\n  end\n\n  doc \"\"\"\n  The audit line for a release offered to the leader: [result] is \"ok\" or an `err_...`\n  word, [why] the reason (\"\" when accepted). One JSON object and a newline.\n\n  ## Examples\n\n      march> Control.audit_release(1000, \"n1\", 2, \"abc\", \"ok\", \"\")\n      \"{\\\"ts\\\":1000,\\\"type\\\":\\\"release\\\",\\\"leader\\\":\\\"n1\\\",\\\"seq\\\":2,\\\"release\\\":\\\"abc\\\",\\\"result\\\":\\\"ok\\\",\\\"why\\\":\\\"\\\"}\\n\"\n  \"\"\"\n  fn audit_release(ts : Int, leader : String, seq : Int, digest : String, result : String, why : String) : String do\n    audit_json(ts, \"release\", leader, [(\"seq\", Json.Number(int_to_float(seq))), (\"release\", Json.Str(digest)), (\"result\", Json.Str(result)), (\"why\", Json.Str(why))])\n  end\n\n  doc \"\"\"\n  The audit line for an order sent to a node (its signed lines are not logged).\n\n  ## Examples\n\n      march> let ord = { seq: 1, release: \"abc\", step: 1, node: \"a\", action: \"activate(web)\", want: \"m1\", artifacts: \"m1\", lines: \"\" }\n      march> Control.audit_order(1000, \"n1\", ord)\n      \"{\\\"ts\\\":1000,\\\"type\\\":\\\"order\\\",\\\"leader\\\":\\\"n1\\\",\\\"seq\\\":1,\\\"release\\\":\\\"abc\\\",\\\"step\\\":1,\\\"node\\\":\\\"a\\\",\\\"action\\\":\\\"activate(web)\\\",\\\"artifacts\\\":\\\"m1\\\"}\\n\"\n  \"\"\"\n  fn audit_order(ts : Int, leader : String, o : StepOrder) : String do\n    audit_json(ts, \"order\", leader, [(\"seq\", Json.Number(int_to_float(o.seq))), (\"release\", Json.Str(o.release)), (\"step\", Json.Number(int_to_float(o.step))),\n      (\"node\", Json.Str(o.node)), (\"action\", Json.Str(o.action)), (\"artifacts\", Json.Str(o.artifacts))])\n  end\n\n  doc \"\"\"\n  The audit line for a node's answer to an order.\n\n  ## Examples\n\n      march> Control.audit_step(1000, \"n1\", { seq: 1, step: 1, node: \"a\", ok: true, detail: \"applied\" })\n      \"{\\\"ts\\\":1000,\\\"type\\\":\\\"step\\\",\\\"leader\\\":\\\"n1\\\",\\\"seq\\\":1,\\\"step\\\":1,\\\"node\\\":\\\"a\\\",\\\"result\\\":\\\"ok\\\",\\\"why\\\":\\\"applied\\\"}\\n\"\n  \"\"\"\n  fn audit_step(ts : Int, leader : String, res : StepResult) : String do\n    audit_json(ts, \"step\", leader, [(\"seq\", Json.Number(int_to_float(res.seq))), (\"step\", Json.Number(int_to_float(res.step))), (\"node\", Json.Str(res.node)),\n      (\"result\", Json.Str(if res.ok do \"ok\" else \"err\" end)), (\"why\", Json.Str(res.detail))])\n  end\n\n  doc \"\"\"\n  The audit line for a release's end: a halt (with its step, node and reason) or completion;\n  None for any other decision.\n\n  ## Examples\n\n      march> Control.audit_decision(1000, \"n1\", 1, Control.RolloutComplete)\n      Some(\"{\\\"ts\\\":1000,\\\"type\\\":\\\"complete\\\",\\\"leader\\\":\\\"n1\\\",\\\"seq\\\":1}\\n\")\n      march> Control.audit_decision(1000, \"n1\", 1, Control.RolloutWait(1, \"gate\"))\n      None\n  \"\"\"\n  fn audit_decision(ts : Int, leader : String, seq : Int, d : CtlDecision) : Option(String) do\n    match d do\n      RolloutHalted(st, n, why) ->\n        Some(audit_json(ts, \"halt\", leader, [(\"seq\", Json.Number(int_to_float(seq))), (\"step\", Json.Number(int_to_float(st))), (\"node\", Json.Str(n)), (\"why\", Json.Str(why))]))\n      RolloutComplete -> Some(audit_json(ts, \"complete\", leader, [(\"seq\", Json.Number(int_to_float(seq)))]))\n      _ -> None\n    end\n  end\nend\n";
